import express from 'express';
import { z } from 'zod';

class HttpError extends Error {
  constructor(status, message) {
    super(message);
    this.status = status;
  }
}
const menu = [{ id: 1, nama: 'Kopi' }];
const app = express();
app.use(express.json());
app.get('/menu/:id', async (req, res) => {
  const m = menu.find((x) => x.id === Number(req.params.id));
  if (!m) throw new HttpError(404, 'Menu tidak ada');
  res.json(m);
});
app.post('/menu', (req, res) => {
  const data = z.object({ nama: z.string() }).parse(req.body);
  res.status(201).json(data);
});
app.get('/bug', () => {
  null.nama;
});
app.use((req, res) => res.status(404).json({ error: 'Jalur tidak ditemukan' }));
app.use((err, req, res, next) => {
  if (err instanceof z.ZodError) return res.status(400).json({ error: 'Data tidak valid' });
  if (err.status && err.status < 500) return res.status(err.status).json({ error: err.message });
  res.status(500).json({ error: 'Terjadi kesalahan di server' });
});
const server = app.listen(3000);

const u = 'http://localhost:3000';
for (const [method, jalur, body] of [['GET', '/menu/9'], ['POST', '/menu', {}], ['GET', '/bug'], ['GET', '/kasir'], ['POST', '/menu', '{rusak']]) {
  const r = await fetch(u + jalur, { method, headers: { 'Content-Type': 'application/json' }, body: typeof body === 'string' ? body : body && JSON.stringify(body) });
  console.log(method, jalur, r.status, (await r.json()).error);
}
server.close();

